import {decisionModulesView,decisionModuleView,journeyView,chooseDomain,moveJourney,reviewRecord} from './experience-ui.js';
import {demoGraph} from './data.js';
import {modules} from './modules.js';
import {modulesView,moduleView,readinessView,builderView,setEditor,getEditor} from './modules-ui.js';
import {saveContextRecord} from './context-editor.js';
import {money,findNode,neighborhood,businessImpact,portfolio,summary,assessment,scenario,scenarioPresets,validateGraph,answerQuestion} from './engine.js';

const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',graph:'M12 3v5 M5 17l5-5 M19 17l-5-5 M9 9a3 3 0 1 0 6 0a3 3 0 1 0-6 0 M2 19a2 2 0 1 0 4 0a2 2 0 1 0-4 0 M18 19a2 2 0 1 0 4 0a2 2 0 1 0-4 0',impact:'M12 3a9 9 0 1 0 9 9 M12 7a5 5 0 1 0 5 5 M12 12l8-8 M16 4h4v4',layers:'M12 3L2 8l10 5 10-5-10-5 M2 12l10 5 10-5 M2 16l10 5 10-5',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3 M20 2v4 M18 4h4',check:'M5 12l4 4L20 5 M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h9',database:'M21 6c0 2.2-4 4-9 4S3 8.2 3 6s4-4 9-4 9 1.8 9 4 M3 6v12c0 2.2 4 4 9 4s9-1.8 9-4V6 M3 12c0 2.2 4 4 9 4s9-1.8 9-4',arrow:'M4 12h16 M15 7l5 5-5 5',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0a9 9 0 1 1 18 0',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3 M8 12l3 3 5-6',alert:'M12 3L2 21h20L12 3 M12 9v5 M12 17v1',chevron:'M9 5l7 7-7 7',search:'M10 18a8 8 0 1 1 0-16a8 8 0 1 1 0 16 M16 16l6 6',menu:'M3 6h18 M3 12h18 M3 18h18',close:'M5 5l14 14 M19 5L5 19',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v5h16v-5',brief:'M7 3h10l4 4v14H3V3h4 M16 3v5h5 M7 12h10 M7 16h7',wallet:'M3 5h16v15H3z M3 8h18v7h-7V8',refresh:'M20 8a8 8 0 1 0 0 9 M20 3v5h-5',link:'M10 13l4-4 M8 16H6a4 4 0 0 1 0-8h4 M14 8h4a4 4 0 0 1 0 8h-4'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.layers}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const typeColors={Objective:'#b47b57',Capability:'#679c86',Process:'#7d9bad',Application:'#588eab',Technology:'#9a81af',Tool:'#7c98a3',Interface:'#8b9c6b',Data:'#ae9974',Risk:'#bf8170',Initiative:'#7e9d70',KPI:'#ac9b5c',Team:'#8b9b92',Contract:'#ab9e8e'};
const pageNames={overview:'Transformation overview',modules:'CIO Decision Modules',builder:'Build Enterprise Context',readiness:'Context readiness',graph:'Enterprise context graph',impact:'Business impact analysis',portfolio:'Portfolio intelligence',scenarios:'Scenario planner',advisor:'CIO intelligence advisor',decisions:'Decision register',data:'Context & evidence'};
Object.assign(pageNames,{modules:'CIO Decision Modules',builder:'Build Enterprise Context',readiness:'Context readiness'});
modules.forEach(m=>Object.defineProperty(pageNames,'module-'+m.id,{value:m.name,enumerable:false}));
let graph=structuredClone(demoGraph),backend='Browser demo',page=location.hash.slice(1)||'overview',selected='app-policy',graphDepth=2,graphType='All types',graphSearch='',portfolioSearch='',portfolioFilter='All dispositions',impactTarget='tech-db',preset='balanced',horizon=36,budget=1000000,selectedInitiatives=[...scenarioPresets.balanced],messages=[],drawer=null;
let decisions=readLocal('cio-decisions',[]), localGraph=readLocal('cio-context',null);
function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function saveLocal(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('Browser storage is unavailable. Export your work before closing.');return false;}}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4200);}
function tag(text,kind=''){return `<span class="tag ${kind}">${esc(text)}</span>`;}
function btn(text,action,kind='',ico='arrow',extra=''){return `<button class="btn ${kind}" data-action="${action}" ${extra}>${ico?icon(ico):''}${text}</button>`;}
function go(next){if(!canLeaveEditor())return;page=next;drawer=null;location.hash=next;render();window.scrollTo({top:0});}
function byType(type){return graph.nodes.filter(n=>n.type===type);}
function getSelected(){return findNode(graph,selected)||graph.nodes[0];}
function nodeButton(id){const n=findNode(graph,id);return n?`<button class="citation" data-node="${esc(n.id)}">${esc(n.name)}</button>`:'';}
function metric(label,value,note,ico='layers',className=''){return `<div class="metric"><div class="metric-top">${label}<span class="metric-symbol">${icon(ico)}</span></div><div class="metric-value">${value}</div><div class="metric-bottom ${className}">${note}</div></div>`;}
function heading(title,sub,actions=''){return `<div class="heading"><div><div class="eyebrow">Enterprise context. Informed transformation.</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="buttons">${actions}</div></div>`;}
function footer(){return `<footer class="footer"><span>Intelligent CIO Transformation Workbench · Prototype v0.3</span><span>${esc(graph.meta.name)} · ${graph.meta.synthetic?'Synthetic demonstration data':'User-supplied context'} · GBP · ${esc(graph.meta.asOf||'Date unspecified')}</span></footer>`;}
function shell(content){return `<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-icon">${icon('graph')}</div><div class="brand-title">Intelligent CIO<span><br>Transformation Workbench</span></div></div><div class="nav-label">Intelligence workspace</div><nav aria-label="Main navigation">${Object.entries(pageNames).map(([id,name])=>`<button class="nav-btn ${page===id?'active':''}" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon({overview:'grid',graph:'graph',impact:'impact',portfolio:'layers',scenarios:'layers',advisor:'spark',decisions:'check',data:'database'}[id])}<span>${name.replace('Transformation overview','Overview').replace('Enterprise context graph','Enterprise graph').replace('Business impact analysis','Impact analysis').replace('CIO intelligence advisor','CIO advisor').replace('Scenario planner','Scenarios')}</span>${id==='decisions'?`<span class="nav-count">${decisions.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="context-box"><strong><span class="dot"></span>Connected enterprise context</strong><p>${graph.nodes.length} entities · ${graph.edges.length} relationships<br>Evidence snapshot: ${esc(graph.meta.asOf||'Not provided')}</p></div><div class="profile"><span class="avatar">SR</span><div><b>Subrata Roy</b><p>Demonstration workspace</p></div></div></div></aside><div class="workspace"><header class="topbar"><div class="crumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><span class="crumb-parent">Intelligence workspace</span><span class="crumb-parent">/</span><b>${pageNames[page]||pageNames.overview}</b></div><div class="top-actions"><span class="environment"><span class="dot"></span>${esc(backend)}</span><button class="icon-button" data-page="data" aria-label="Context and data settings">${icon('database')}</button><span class="avatar">SR</span></div></header><main id="main" class="main" tabindex="-1">${page==='overview'?`<div class="module-launch panel"><div><b>Start with your enterprise. Then explore decisions.</b><p>Build enterprise context, inspect evidence gaps and connect transformation decisions.</p></div><button class="btn primary" data-page="modules">Explore CIO decision modules</button></div>`:''}${content}${footer()}</main></div></div>${drawer?drawerView():''}`;}
function overview(){const s=summary(graph);const riskAssets=portfolio(graph).filter(n=>n.risk>=60);const opportunities=byType('Initiative');const savings=opportunities.reduce((a,n)=>a+n.annualSaving,0);return `${heading('Your enterprise. Connected.', 'Turn enterprise context into clear, evidence-led transformation choices.',btn('Export CIO brief','export-brief','','download')+btn('Explore enterprise graph','open-graph','primary','graph'))}<div class="status-row"><span><span class="dot"></span>Context snapshot ready</span><span>${icon('clock')}As of ${esc(graph.meta.asOf||'Not provided')}</span><span>${icon('shield')}Evidence-linked decisions</span></div><div class="metric-grid">${metric('Connected estate',s.assets,`${s.entities} entities across ${new Set(graph.nodes.map(n=>n.type)).size} context types`,'layers')}${metric('Recorded annual run cost',money(s.cost),'Application and tool costs · illustrative','wallet')}${metric('Assets with elevated risk',s.highRisk,'Risk score ≥ 60 · owner review required','shield','warning-text')}${metric('Owner-validated entities',`${s.confidence}%`,'Validation flags · not inventory completeness','check','positive')}</div><div class="grid-two"><section class="panel"><div class="panel-head"><div><h2>The enterprise context graph</h2><p>From business intent to technology and transformation</p></div><button class="text-button" data-page="graph">Explore graph ${icon('arrow')}</button></div><div class="graph-mini">${miniGraph()}</div><div class="graph-legend">${['Objective','Capability','Application','Technology','Initiative'].map(t=>`<span><i class="legend-dot" style="background:${typeColors[t]}"></i>${t}</span>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>Where to focus next</h2><p>Signals that deserve a decision</p></div>${tag('3 signals','orange')}</div><div class="insight-list"><div class="insight"><span class="insight-icon">${icon('shield')}</span><div><strong>Business exposure behind technology risk</strong><p>${riskAssets.length} elevated-risk assets in the recorded estate. Trace the capabilities and objectives that depend on them.</p><button class="text-button" data-page="impact">Trace business impact ${icon('arrow')}</button></div></div><div class="insight"><span class="insight-icon green">${icon('layers')}</span><div><strong>${money(savings)} annual opportunity hypothesis</strong><p>${opportunities.length} initiatives with illustrative recurring benefits. Compare investment, timing and dependencies.</p><button class="text-button" data-page="scenarios">Compare transformation options ${icon('arrow')}</button></div></div><div class="insight"><span class="insight-icon">${icon('alert')}</span><div><strong>Evidence gaps can change the answer</strong><p>${graph.nodes.filter(n=>!n.validated).length} entities need owner validation. Resolve uncertainty before committing to change.</p><button class="text-button" data-page="data">Review context quality ${icon('arrow')}</button></div></div></div></section></div><section class="panel"><div class="panel-head" style="padding-bottom:18px"><div><h2>Transformation priorities</h2><p>Transparent assessment logic, connected to business context</p></div><button class="text-button" data-page="portfolio">View portfolio ${icon('arrow')}</button></div>${assetTable(portfolio(graph).sort((a,b)=>(assessment(b).priority??-1)-(assessment(a).priority??-1)).slice(0,5),true)}</section><div class="section-gap data-health">${icon('shield')}All values are illustrative. Recommendations are review proposals; benefits are unvalidated hypotheses.</div>`;}
function miniGraph(){const preferred=['obj-growth','obj-resilience','obj-efficiency','cap-service','cap-claims','cap-finance','app-policy','app-claims','app-report','tech-db','init-policy','init-report'];let nodes=preferred.map(id=>findNode(graph,id)).filter(Boolean);if(nodes.length<5)nodes=graph.nodes.slice(0,12);const positions=new Map();const rows={Objective:0,Capability:1,Application:2,Technology:3,Initiative:3};for(let row=0;row<4;row++){const ns=nodes.filter(n=>(rows[n.type]??3)===row);ns.forEach((n,i)=>positions.set(n.id,{x:70+(i+.5)*(530/Math.max(1,ns.length)),y:30+row*66}));}const edges=graph.edges.filter(e=>positions.has(e.source)&&positions.has(e.target));return `<svg viewBox="0 0 670 278" role="img" aria-label="Interactive enterprise context preview"><defs><marker id="mini-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="4" markerHeight="4" orient="auto"><path d="M0 0L10 5L0 10" fill="#bccfc2"/></marker></defs>${edges.map(e=>{const a=positions.get(e.source),b=positions.get(e.target);return `<path class="edge" d="M${a.x} ${a.y+12} Q${a.x} ${(a.y+b.y)/2} ${b.x} ${b.y-12}" marker-end="url(#mini-arrow)" ${e.state!=='observed'?'stroke-dasharray="4 4"':''}/>`;}).join('')}${nodes.map(n=>{const p=positions.get(n.id);return `<g class="graph-node" data-graphnode="${esc(n.id)}" role="button" tabindex="0" aria-label="Explore ${esc(n.name)}"><rect x="${p.x-66}" y="${p.y-13}" width="132" height="27" rx="6" fill="white" stroke="${typeColors[n.type]||'#7e9d70'}" stroke-opacity=".45"/><circle cx="${p.x-53}" cy="${p.y+.5}" r="3" fill="${typeColors[n.type]||'#7e9d70'}"/><text x="${p.x-43}" y="${p.y+4}" font-size="8.5" fill="#4d6758">${esc(n.name.length>22?n.name.slice(0,20)+'…':n.name)}</text></g>`;}).join('')}</svg>`;}
function assetTable(assets,compact=false){return `<div class="table-wrap"><table class="table"><thead><tr><th>Application / tool</th><th>Business value</th><th>Technical health</th><th>Risk</th>${compact?'':'<th>Annual cost</th>'}<th>Proposed action</th><th>Evidence</th><th></th></tr></thead><tbody>${assets.length?assets.map(n=>{const a=assessment(n);return `<tr><td><div class="asset-name"><span class="asset-mark">${esc(n.name.slice(0,2).toUpperCase())}</span><div><button class="view-link" data-node="${esc(n.id)}">${esc(n.name)}</button><small>${esc(n.owner||'Owner not assigned')}</small></div></div></td><td>${bar(n.businessValue)}</td><td>${bar(n.health,n.health<50?'#cc9270':'#6fa78d')}</td><td>${tag(n.risk===undefined?'Unknown':n.risk>=60?'High · '+n.risk:n.risk>=40?'Medium · '+n.risk:'Low · '+n.risk,n.risk>=60?'red':n.risk>=40?'orange':'green')}</td>${compact?'':`<td>${money(n.annualCost||0)}</td>`}<td>${tag(a.action,a.action.includes('modern')?'blue':a.action.includes('Validate')?'orange':'green')}</td><td>${tag(n.validated?'Validated':'Needs review',n.validated?'green':'orange')}</td><td><button class="text-button" data-impact="${esc(n.id)}" aria-label="Trace impact of ${esc(n.name)}">${icon('arrow')}</button></td></tr>`;}).join(''):'<tr><td colspan="8" class="empty">No matching assets. Try another filter or import a portfolio dataset.</td></tr>'}</tbody></table></div>`;}
function bar(value,color='#6fa78d'){return Number.isFinite(value)?`<span class="score-bar"><span class="bar-track"><i style="width:${Math.max(0,Math.min(value,100))}%;background:${color}"></i></span>${value}</span>`:'<span class="muted">Unknown</span>';}
function graphView(){const root=getSelected();if(!root)return heading('Enterprise context graph','Import a graph to begin.');const scope=neighborhood(graph,root.id,graphDepth);const nodes=scope.nodes.filter(n=>(graphType==='All types'||n.type===graphType)&&(!graphSearch||n.name.toLowerCase().includes(graphSearch)));const ids=new Set(nodes.map(n=>n.id));const edges=scope.edges.filter(e=>ids.has(e.source)&&ids.has(e.target));return `${heading('See the enterprise connections.', 'Explore how business objectives, capabilities and the technology estate fit together.',btn('Export context','export-context','','download'))}<div class="toolbar"><label><span class="hidden">Find entity</span><input class="search" id="graph-search" placeholder="Search visible entities…" value="${esc(graphSearch)}"></label><label><span class="hidden">Entity type</span><select class="select" id="graph-type">${['All types',...new Set(graph.nodes.map(n=>n.type))].map(t=>`<option ${graphType===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label><span class="hidden">Neighborhood depth</span><select class="select" id="graph-depth">${[1,2,3].map(d=>`<option value="${d}" ${graphDepth===d?'selected':''}>${d}-hop context</option>`).join('')}</select></label><span class="count-label">${nodes.length} visible entities · ${edges.length} relationships</span></div><div class="graph-layout"><section class="panel"><div class="panel-head" style="padding-bottom:15px"><div><h2>Context around ${esc(root.name)}</h2><p>Select an entity to inspect evidence and recenter the graph</p></div>${tag('Connected context','green')}</div><div class="graph-canvas">${graphSvg(nodes,edges,root.id)}</div><div class="graph-legend">${[...new Set(nodes.map(n=>n.type))].map(t=>`<span><i class="legend-dot" style="background:${typeColors[t]||'#789886'}"></i>${esc(t)}</span>`).join('')}</div><div class="legend">Solid lines: observed relationships · Dashed lines: proposed changes or hypotheses. Arrow direction follows the stored relationship. Filters hide nodes, not underlying context.</div></section><aside class="panel">${detailView(root)}</aside></div>`;}
function graphSvg(nodes,edges,rootId){if(!nodes.length)return '<div class="empty">No entities match these filters.</div>';const width=820,height=Math.max(530,Math.ceil(nodes.length/5)*95);const types=['Objective','Capability','Process','Application','Tool','Technology','Interface','Data','Risk','Initiative','KPI','Team','Contract'];const ordered=[...nodes].sort((a,b)=>types.indexOf(a.type)-types.indexOf(b.type));const pos=new Map();const cols=Math.min(4,Math.ceil(Math.sqrt(nodes.length)));const rows=Math.ceil(nodes.length/cols);ordered.forEach((n,i)=>pos.set(n.id,{x:105+(i%cols)*(610/Math.max(cols-1,1)),y:57+Math.floor(i/cols)*((height-110)/Math.max(rows-1,1))}));return `<svg viewBox="0 0 ${width} ${height}" aria-label="Enterprise context graph"><defs><marker id="graph-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10" fill="#91af9d"/></marker></defs>${edges.map(e=>{const a=pos.get(e.source),b=pos.get(e.target),dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,ax=a.x+dx/len*38,ay=a.y+dy/len*24,bx=b.x-dx/len*42,by=b.y-dy/len*24;const focus=e.source===rootId||e.target===rootId;return `<path class="edge ${focus?'focus':''}" d="M${ax} ${ay} Q${(a.x+b.x)/2+15} ${(a.y+b.y)/2-12} ${bx} ${by}" marker-end="url(#graph-arrow)" ${e.state!=='observed'?'stroke-dasharray="5 4"':''}/>${focus?`<text class="edge-label" x="${(a.x+b.x)/2+6}" y="${(a.y+b.y)/2-10}" text-anchor="middle">${esc(e.type.toLowerCase().replaceAll('_',' '))}</text>`:''}`;}).join('')}${ordered.map(n=>{const p=pos.get(n.id),c=typeColors[n.type]||'#799984',active=n.id===rootId;return `<g class="graph-node" data-graphnode="${esc(n.id)}" role="button" tabindex="0" aria-label="Explore ${esc(n.name)}"><title>${esc(n.name)} · ${esc(n.type)}</title>${active?`<rect x="${p.x-88}" y="${p.y-28}" width="176" height="56" rx="10" fill="${c}" opacity=".10"/>`:''}<rect x="${p.x-82}" y="${p.y-22}" width="164" height="44" rx="7" fill="white" stroke="${c}" stroke-width="${active?2:1}" stroke-opacity="${active?1:.5}"/><circle cx="${p.x-68}" cy="${p.y-7}" r="3.5" fill="${c}"/><text x="${p.x-58}" y="${p.y-4}" font-size="8" fill="${c}">${esc(n.type)}</text><text x="${p.x-68}" y="${p.y+11}" font-size="9.5" font-weight="500" fill="#344f40">${esc(n.name.length>25?n.name.slice(0,23)+'…':n.name)}</text></g>`;}).join('')}</svg>`;}
function detailView(n){const connections=graph.edges.filter(e=>e.source===n.id||e.target===n.id);const props=[['Accountable owner',n.owner||'Unassigned'],['Annual run cost',n.annualCost!==undefined?money(n.annualCost,false):null],['Business value',n.businessValue!==undefined?`${n.businessValue} / 100`:null],['Technical health',n.health!==undefined?`${n.health} / 100`:null],['Risk score',n.risk!==undefined?`${n.risk} / 100`:null],['Support end',n.supportEnd],['Baseline',n.baseline],['Target',n.target],['Investment',n.investment!==undefined?money(n.investment):null],['Annual saving hypothesis',n.annualSaving!==undefined?money(n.annualSaving):null]];return `<div class="detail"><div class="type-label">${esc(n.type)} · ${esc(n.id)}</div><h2>${esc(n.name)}</h2><div class="tag-row">${tag(n.validated?'Owner validated':'Needs validation',n.validated?'green':'orange')}${tag(n.confidence||'Unknown confidence')}</div>${n.description?`<p>${esc(n.description)}</p>`:''}<dl>${props.filter(([,v])=>v!==undefined&&v!==null).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="evidence"><strong>Evidence provenance</strong>${esc(n.source||'Source not provided')}<br>Observed: ${esc(n.observedAt||'Unknown')}<br>${graph.meta.synthetic?'Synthetic demonstration evidence':'User-supplied evidence; verify source authority'}</div><h3>${connections.length} connected relationships</h3>${connections.slice(0,8).map(e=>{const other=findNode(graph,e.source===n.id?e.target:e.source);return other?`<button class="connection" data-graphnode="${esc(other.id)}"><small>${esc(e.source===n.id?'→ ':'← ')}${esc(e.type.replaceAll('_',' '))} · ${esc(e.state||'unspecified')} ${e.validated?'':'· unvalidated'}</small>${esc(other.name)}</button>`:'';}).join('')}${connections.length>8?`<p>+ ${connections.length-8} more in graph context</p>`:''}${btn('Trace business impact','trace-selected','primary','impact',`data-id="${esc(n.id)}"`)}${['Application','Tool'].includes(n.type)?btn('Create review decision','create-decision','','check',`data-id="${esc(n.id)}"`):''}</div>`;}
function impactView(){if(!findNode(graph,impactTarget))impactTarget=graph.nodes[0]?.id;const target=findNode(graph,impactTarget);if(!target)return heading('Business impact analysis','Import enterprise context first.');const impact=businessImpact(graph,target.id);const caps=impact.filter(x=>x.node.type==='Capability'),apps=impact.filter(x=>x.node.type==='Application'),objs=impact.filter(x=>x.node.type==='Objective');return `${heading('Understand the business consequence.', 'Trace recorded dependencies from a technology or application to the business outcomes it supports.',btn('View source entity','impact-source','','graph'))}<div class="toolbar"><label for="impact-select" class="section-caption">Explore exposure from</label><select class="select" id="impact-select">${graph.nodes.filter(n=>['Application','Technology','Tool','Interface','Data'].includes(n.type)).map(n=>`<option value="${esc(n.id)}" ${target.id===n.id?'selected':''}>${esc(n.name)} · ${esc(n.type)}</option>`).join('')}</select></div><div class="impact-grid"><div class="impact-stat"><b>${apps.length}</b><span>Dependent applications</span></div><div class="impact-stat"><b>${caps.length}</b><span>Connected business capabilities</span></div><div class="impact-stat"><b>${objs.length}</b><span>Strategic objectives with exposure paths</span></div></div><div class="notice info">${icon('link')} Impact follows recorded, observed dependencies in reverse. Paths show potential exposure; they do not establish outage propagation or business causation. Missing dependencies remain unknown.</div><div class="grid-two"><section class="panel"><div class="panel-head" style="padding-bottom:20px"><div><h2>Business exposure paths</h2><p>One shortest recorded path per affected entity</p></div>${tag(`${impact.length} reached entities`,'green')}</div>${impact.length?impact.sort((a,b)=>b.path.length-a.path.length).map(({node,path})=>`<div class="path-row"><div style="display:flex;justify-content:space-between;gap:10px"><button class="view-link" data-node="${esc(node.id)}">${esc(node.name)}</button>${tag(node.type)}</div><div class="path">${path.map((id,i)=>` ${i?'<i>←</i>':''}<span>${esc(findNode(graph,id).name)}</span>`).join('')}</div></div>`).join(''):'<div class="empty">No upstream dependencies are recorded. This is not confirmation of zero business impact.</div>'}</section><aside class="panel">${detailView(target)}</aside></div>`;}
function portfolioView(){const assets=portfolio(graph).filter(n=>(!portfolioSearch||`${n.name} ${n.owner}`.toLowerCase().includes(portfolioSearch))&&(portfolioFilter==='All dispositions'||assessment(n).action===portfolioFilter));return `${heading('Prioritize with the evidence in view.', 'Review application and tool health, business value, risk and decision readiness.',btn('Export assessment CSV','export-portfolio','','download'))}<div class="notice info">Assessment rule v1: 45% risk + 35% technical weakness + 20% business value. Scores prioritize review; proposed dispositions require validation and approval.</div><div class="toolbar"><input class="search" id="portfolio-search" aria-label="Search portfolio" placeholder="Search applications, tools or owners…" value="${esc(portfolioSearch)}"><select class="select" id="portfolio-filter" aria-label="Filter assessment action">${['All dispositions',...new Set(portfolio(graph).map(n=>assessment(n).action))].map(s=>`<option ${s===portfolioFilter?'selected':''}>${esc(s)}</option>`).join('')}</select><span class="count-label">${assets.length} of ${portfolio(graph).length} assets</span></div><section class="panel">${assetTable(assets.sort((a,b)=>(assessment(b).priority??-1)-(assessment(a).priority??-1)))}</section>`;}
function scenariosView(){selectedInitiatives=selectedInitiatives.filter(id=>findNode(graph,id)?.type==='Initiative');const calc=scenario(graph,selectedInitiatives,horizon,budget);const initiatives=byType('Initiative');return `${heading('Compare the choices. See the trade-offs.', 'Explore investment, implementation timing and value hypotheses across transformation options.',btn('Export scenario','export-scenario','','download')+btn('Record scenario review','scenario-decision','primary','check'))}<div class="scenario-layout"><aside class="panel scenario-controls"><h3>Build your transformation option</h3><label class="form-label">Starting point</label><div class="preset-row">${[['balanced','Balanced'],['risk','Risk first'],['cost','Cost first']].map(([id,name])=>`<button class="btn ${preset===id?'accent':''}" data-preset="${id}">${name}</button>`).join('')}</div><div><label class="form-label" for="budget">Investment budget <span class="muted">${money(budget)}</span></label><input id="budget" class="range" type="range" min="200000" max="2000000" step="50000" value="${budget}"><div class="range-labels"><span>£200k</span><span>£2m</span></div><label class="form-label" for="horizon">Evaluation horizon</label><select id="horizon" class="select" style="width:100%">${[12,24,36,48,60].map(m=>`<option value="${m}" ${horizon===m?'selected':''}>${m} months</option>`).join('')}</select></div><div><label class="form-label">Initiatives to include</label>${initiatives.map(n=>`<label class="choice"><input type="checkbox" data-initiative="${esc(n.id)}" ${selectedInitiatives.includes(n.id)?'checked':''}><span>${esc(n.name)}<small>${money(n.investment)} investment · ${n.durationMonths} months<br>${money(n.annualSaving)} annual saving hypothesis</small></span></label>`).join('')||'<p class="section-caption">Import initiatives to compare scenarios.</p>'}</div></aside><div><div class="scenario-metrics">${metric('Upfront investment',money(calc.investment),`Budget: ${money(budget)}`,'wallet')}${metric('Steady-state annual savings',money(calc.annualSaving),'Unvalidated recurring benefit hypothesis','layers')}${metric(`${horizon}-month net benefit`,money(calc.netBenefit),'Undiscounted, after implementation delays','impact',calc.netBenefit>=0?'positive':'warning-text')}</div>${calc.warnings.length?`<div class="notice"><b>Review these constraints</b><br>${calc.warnings.map(esc).join('<br>')}</div>`:'<div class="notice info">Selected initiatives fit the modelled budget and dependency constraints. Benefit and delivery assumptions still require review.</div>'}<section class="panel"><div class="panel-head"><div><h2>Dependency-aware implementation sequence</h2><p>Dependent initiatives start after selected predecessors finish</p></div>${tag('Proposed plan','orange')}</div><div class="schedule"><div class="range-labels" style="margin-left:164px"><span>Month 0</span><span>Month ${horizon}</span></div>${calc.schedule.map(row=>`<div class="schedule-row"><span>${esc(row.name)}</span><div class="schedule-track"><span class="schedule-bar" style="left:${Math.min(100,row.start/horizon*100)}%;width:${Math.max(0,Math.min(row.end,horizon)-Math.min(row.start,horizon))/horizon*100}%">M${row.start}–${row.end}</span></div></div>`).join('')||'<div class="empty">Select an initiative to build a scenario.</div>'}</div><div class="legend">Implementation costs are charged upfront. Savings start after completion, accrue monthly, and remain flat. No discounting, tax, inflation, delivery-capacity limits or additional transition costs are modelled.</div></section><section class="panel section-gap"><div class="panel-head" style="padding-bottom:17px"><div><h2>Compare starting options</h2><p>Same budget and horizon applied to every option</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Option</th><th>Investment</th><th>Annual savings</th><th>Net benefit</th><th>Model constraints</th></tr></thead><tbody>${Object.entries(scenarioPresets).map(([id,ids])=>{const available=ids.filter(x=>findNode(graph,x));if(!available.length)return `<tr><td>${esc(id)}</td><td colspan="4">No matching initiatives in this dataset</td></tr>`;const c=scenario(graph,available,horizon,budget);return `<tr><td><button class="view-link" data-preset="${id}">${{balanced:'Balanced',risk:'Risk first',cost:'Cost first'}[id]}</button></td><td>${money(c.investment)}</td><td>${money(c.annualSaving)}</td><td>${money(c.netBenefit)}</td><td>${tag(c.warnings.length?`${c.warnings.length} review flags`:'Within model',c.warnings.length?'orange':'green')}</td></tr>`;}).join('')}</tbody></table></div></section></div></div>`;}
const suggestedQuestions=['What is the business impact of the Legacy database platform?','Which applications have elevated risk?','What is our total annual run cost?','Why should we modernize PolicyCore?','Compare the balanced transformation scenario.','Where is evidence missing?'];
function advisorView(){return `${heading('Ask the question behind the decision.', 'Explore the enterprise through bounded graph tools, calculations and traceable evidence.')}<div class="advisor-layout"><section class="panel"><div class="advisor-welcome"><div class="advisor-orb">${icon('spark')}</div><div class="eyebrow">CIO intelligence advisor</div><h2>What would you like to understand?</h2><p class="section-caption">Start with a business question. Follow the evidence through the enterprise.</p><div class="suggestions">${suggestedQuestions.map(q=>`<button class="suggestion" data-question="${esc(q)}">${esc(q)} <span style="float:right;color:#9daea2">↗</span></button>`).join('')}</div></div><div class="chat-area" id="chat-area">${messages.length?messages.map(m=>`<div class="user-message">${esc(m.question)}</div><article class="answer"><div class="tool-label">${icon('spark')} ${esc(m.answer.tool)} · ${esc(graph.meta.asOf||'Date not supplied')}</div>${tag(m.answer.kind,m.answer.kind==='Evidence gap'?'orange':'green')}<h3>${esc(m.answer.title)}</h3><p>${esc(m.answer.text)}</p><div class="citations">${m.answer.ids.map(nodeButton).join('')}</div></article>`).join(''):'<div class="empty">Your decision context starts with a question.</div>'}</div><form class="chat-form" id="chat-form"><input id="question" placeholder="Ask about impact, risk, spend or transformation options…" aria-label="Your CIO question" maxlength="600" required><button class="btn primary" type="submit">${icon('arrow')} Ask</button></form><div class="legend">Demonstration advisor: deterministic intent routing and graph tools. No language model is connected. Unsupported questions return an evidence-gap response.</div></section><aside class="panel detail"><div class="type-label">How answers are assembled</div><h2>Context before conclusions.</h2>${[['graph','Enterprise relationships','Traverse explicit dependencies and business connections.'],['wallet','Calculation tools','Compute figures from recorded values and scenario assumptions.'],['brief','Evidence references','Open the source entities behind each answer.'],['shield','Decision boundaries','Separate observed evidence, proposals and unknowns.']].map(([i,t,d])=>`<div class="insight">${icon(i)}<div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}<div class="evidence"><strong>Coverage boundary</strong>Answers reflect only the loaded snapshot. Missing relationships and incomplete source systems limit the conclusions.</div>${btn('Clear conversation','clear-chat','','refresh')}</aside></div>`;}
function decisionsView(){return `${heading('Make the decision trail explicit.', 'Record the proposal, evidence, rationale and review outcome.',btn('Export decision register','export-decisions','','download'))}<div class="notice info">Prototype register: decisions are stored in this browser. Status changes demonstrate a workflow and do not authenticate an approver or authorize enterprise change.</div><section class="panel">${decisions.length?decisions.map(d=>`<article class="decision-card"><div class="decision-top"><div><div class="eyebrow">${esc(d.id)} · ${esc(d.createdAt.slice(0,10))}</div><h3>${esc(d.title)}</h3></div>${tag(d.status,d.status==='Approved'?'green':d.status==='Rejected'?'red':'orange')}</div><p>${esc(d.proposal)}</p><div class="tag-row">${tag('Snapshot '+d.snapshot)}${tag('Rule v1')}${d.evidence.map(nodeButton).join('')}</div><label class="form-label" for="rationale-${esc(d.id)}">Reviewer rationale (required for approval or rejection)</label><textarea id="rationale-${esc(d.id)}" data-rationale="${esc(d.id)}" placeholder="Record the evidence considered, conditions and accountable next steps…">${esc(d.rationale||'')}</textarea><div class="buttons">${btn('Save rationale','save-rationale','','check',`data-id="${esc(d.id)}"`)}${d.status==='Pending review'?btn('Approve for planning','approve-decision','primary','check',`data-id="${esc(d.id)}"`)+btn('Reject proposal','reject-decision','','close',`data-id="${esc(d.id)}"`):`<span class="section-caption">Reviewed ${esc(d.reviewedAt?.slice(0,10)||'')} · Demonstration reviewer</span>`}</div></article>`).join(''):`<div class="empty">No decisions recorded yet.<br>Create a review from an asset evidence panel or the scenario planner.<div class="buttons" style="justify-content:center;margin-top:18px">${btn('Explore portfolio','open-portfolio','primary','layers')}</div></div>`}</section>`;}
function dataView(){const types=[...new Set(graph.nodes.map(n=>n.type))];const unvalidated=graph.nodes.filter(n=>!n.validated);return `${heading('Build context you can trust.', 'Inspect source coverage, validate evidence and load your own enterprise graph.',btn('Export current graph','export-context','','download'))}<div class="notice">${graph.meta.synthetic?'You are exploring synthetic data for Northstar Assurance, a fictional company.':'You are exploring user-supplied data. Validate data ownership and source authority before drawing conclusions.'} The static hosted prototype stores imports and decisions in your browser. No authentication, live enterprise connector, or model endpoint is configured.</div><div class="data-grid"><section class="panel data-card">${icon('upload')}<h3>Import enterprise context</h3><p>Load JSON in the sample schema. Validates IDs, references, numeric fields and initiative dependency cycles before replacing context.</p><input type="file" accept="application/json,.json" id="context-file" class="hidden">${btn('Choose JSON file','import-context','primary','upload')}</section><section class="panel data-card">${icon('database')}<h3>Neo4j-ready foundation</h3><p>The source includes a local API, a Neo4j seed script, Docker configuration and a documented graph schema.</p>${tag(backend==='Neo4j connected'?'Neo4j connected':'Optional local backend',backend==='Neo4j connected'?'green':'orange')}<br>${btn('Download sample graph','download-sample','','download')}</section><section class="panel data-card">${icon('refresh')}<h3>Reset demonstration</h3><p>Restore the synthetic context and starting scenarios. Existing decisions stay in this browser unless you clear them separately.</p>${btn('Restore demo context','reset-context','','refresh')} ${btn('Clear decisions','clear-decisions','','close')}</section></div><div class="grid-two section-gap"><section class="panel"><div class="panel-head" style="padding-bottom:17px"><div><h2>Context coverage</h2><p>Entity counts describe the loaded snapshot, not enterprise completeness</p></div>${tag(`${graph.nodes.length} entities`,'green')}</div>${types.map(t=>{const ns=byType(t);const count=ns.filter(n=>n.validated).length;return `<div class="coverage-row"><i class="legend-dot" style="background:${typeColors[t]||'#789886'}"></i><span>${esc(t)}</span><span class="bar-track"><i style="width:${count/ns.length*100}%"></i></span><span class="muted">${count}/${ns.length} validated</span></div>`;}).join('')}</section><section class="panel"><div class="panel-head" style="padding-bottom:17px"><div><h2>Evidence awaiting validation</h2><p>Review with the accountable data owner</p></div>${tag(`${unvalidated.length} open`,'orange')}</div>${unvalidated.length?unvalidated.map(n=>`<div class="path-row"><button class="view-link" data-node="${esc(n.id)}">${esc(n.name)}</button><p class="section-caption" style="margin-top:6px">${esc(n.owner||'Owner unassigned')} · ${esc(n.confidence||'Unknown')} confidence</p></div>`).join(''):'<div class="empty">All loaded entities are marked validated. This does not prove source coverage or accuracy.</div>'}<div class="data-health">${icon('shield')}Relationships: ${graph.edges.filter(e=>e.validated).length}/${graph.edges.length} marked validated</div></section></div>`;}
function drawerView(){const n=findNode(graph,drawer);if(!n)return '';return `<div class="detail-overlay" data-action="close-overlay"><aside class="detail-drawer" role="dialog" aria-modal="true" aria-label="Entity evidence: ${esc(n.name)}"><div class="drawer-head"><span>Enterprise context · evidence</span><button class="icon-button" data-action="close-drawer" aria-label="Close evidence panel">${icon('close')}</button></div>${detailView(n)}</aside></div>`;}
let contextDirty=false;
function canLeaveEditor(){return !contextDirty||confirm('You have unsaved changes. Leave this form without saving?');}
function render(){contextDirty=false;if(!pageNames[page])page='overview';const views={overview,graph:graphView,impact:impactView,portfolio:portfolioView,scenarios:scenariosView,advisor:advisorView,decisions:decisionsView,data:dataView,modules:()=>decisionModulesView(graph),builder:()=>journeyView(graph),readiness:()=>readinessView(graph)};const content=page.startsWith('module-')?decisionModuleView(graph,page.slice(7)):views[page]();document.querySelector('#app').innerHTML=shell(content);document.title=`${pageNames[page]} · Intelligent CIO`;}
function download(name,content,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Export downloaded.');}
function addDecision(title,proposal,evidence,details={}){const d={id:'DEC-'+crypto.randomUUID().slice(0,8).toUpperCase(),title,proposal,evidence,status:'Pending review',rationale:'',createdAt:new Date().toISOString(),snapshot:graph.meta.asOf||'Unknown',ruleVersion:'v1',...details};decisions.unshift(d);saveLocal('cio-decisions',decisions);go('decisions');toast('Review decision recorded in this browser.');}
function ask(question){messages.push({question,answer:answerQuestion(graph,question)});render();const area=document.querySelector('#chat-area');if(area)area.scrollTop=area.scrollHeight;document.querySelector('#question')?.focus();}
function openGraph(id){selected=id;graphType='All types';graphSearch='';go('graph');}
function exportBrief(){const s=summary(graph);const content=`# Intelligent CIO Transformation Workbench\n\nEnterprise: ${graph.meta.name}\nSnapshot: ${graph.meta.asOf}\nSynthetic data: ${!!graph.meta.synthetic}\n\n## Estate\n\n${s.entities} entities; ${s.relationships} relationships; ${s.assets} applications and tools.\nRecorded annual run cost: ${money(s.cost,false)}.\nElevated-risk assets: ${s.highRisk}.\nOwner-validated entities: ${s.confidence}% (not inventory completeness).\n\n## Review priorities\n\n${portfolio(graph).sort((a,b)=>(assessment(b).priority??-1)-(assessment(a).priority??-1)).map(n=>`- ${n.name}: ${assessment(n).action}; priority ${assessment(n).priority??'unavailable'}; evidence ${n.validated?'validated':'requires review'}.`).join('\n')}\n\n## Boundaries\n\nAll demonstration benefits are hypotheses. Context coverage is limited to loaded records. No enterprise decision has been automatically approved.\n`;
download('cio-transformation-brief.md',content,'text/markdown');}
document.addEventListener('click',event=>{const t=event.target.closest('[data-page],[data-action],[data-node],[data-graphnode],[data-impact],[data-preset],[data-question]');if(!t)return;if(t.dataset.page){go(t.dataset.page);return;}if(t.dataset.graphnode){openGraph(t.dataset.graphnode);return;}if(t.dataset.node){drawer=t.dataset.node;render();document.querySelector('[data-action="close-drawer"]')?.focus();return;}if(t.dataset.impact){impactTarget=t.dataset.impact;go('impact');return;}if(t.dataset.preset){preset=t.dataset.preset;selectedInitiatives=scenarioPresets[preset].filter(id=>findNode(graph,id));render();return;}if(t.dataset.question){ask(t.dataset.question);return;}const action=t.dataset.action;const id=t.dataset.id;switch(action){
case 'menu':document.querySelector('#sidebar').classList.toggle('open');break;
case 'open-graph':go('graph');break;case 'open-portfolio':go('portfolio');break;
case 'close-overlay':if(event.target===t){drawer=null;render();}break;case 'close-drawer':drawer=null;render();break;
case 'trace-selected':impactTarget=id;go('impact');break;case 'impact-source':openGraph(impactTarget);break;
case 'create-decision':{const n=findNode(graph,id),a=assessment(n);addDecision(`${a.action}: ${n.name}`,`${a.rule} Proposed action requires accountable owner review.`,[id],{assessmentSnapshot:structuredClone(n),assessment:a});break;}
case 'scenario-decision':{if(!selectedInitiatives.length){toast('Select at least one initiative first.');break;}const calc=scenario(graph,selectedInitiatives,horizon,budget);addDecision(`Review ${preset==='custom'?'custom':preset} transformation option`,`${money(calc.investment)} investment; ${money(calc.annualSaving)} annual saving hypothesis; ${money(calc.netBenefit)} undiscounted net benefit over ${horizon} months. ${calc.warnings.length?calc.warnings.join(' '):'Within modelled constraints; validation still required.'}`,[...selectedInitiatives],{scenarioSnapshot:{ids:[...selectedInitiatives],horizon,budget,calculation:calc}});break;}
case 'save-rationale':case 'approve-decision':case 'reject-decision':{const d=decisions.find(x=>x.id===id),value=document.getElementById(`rationale-${id}`).value.trim();if(action!=='save-rationale'&&!value){toast('Record a rationale before approving or rejecting.');break;}d.rationale=value;if(action!=='save-rationale'){d.status=action==='approve-decision'?'Approved':'Rejected';d.reviewedAt=new Date().toISOString();}saveLocal('cio-decisions',decisions);render();toast('Decision register updated.');break;}
case 'export-brief':exportBrief();break;
case 'export-context':download('enterprise-context.json',JSON.stringify(graph,null,2));break;
case 'download-sample':download('sample-enterprise-context.json',JSON.stringify(demoGraph,null,2));break;
case 'export-decisions':download('cio-decision-register.json',JSON.stringify(decisions,null,2));break;
case 'export-scenario':download('transformation-scenario.json',JSON.stringify({snapshot:graph.meta,ids:selectedInitiatives,horizon,budget,result:scenario(graph,selectedInitiatives,horizon,budget)},null,2));break;
case 'export-portfolio':{const rows=[['Name','Owner','Type','Annual cost GBP','Business value','Technical health','Risk','Priority','Proposed action','Evidence'],...portfolio(graph).map(n=>[n.name,n.owner,n.type,n.annualCost,n.businessValue,n.health,n.risk,assessment(n).priority,assessment(n).action,n.validated?'Validated':'Needs review'])];const csv=rows.map(r=>r.map(v=>`"${String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')}"`).join(',')).join('\r\n');download('portfolio-assessment.csv',csv,'text/csv');break;}
case 'import-context':document.querySelector('#context-file').click();break;
case 'reset-context':graph=structuredClone(demoGraph);saveLocal('cio-context',null);selected='app-policy';impactTarget='tech-db';selectedInitiatives=[...scenarioPresets.balanced];messages=[];backend='Browser demo';render();toast('Synthetic demonstration context restored.');break;
case 'clear-decisions':if(decisions.length&&confirm('Clear all locally stored prototype decisions? Export first if you need a copy.')){decisions=[];saveLocal('cio-decisions',[]);render();toast('Local decision register cleared.');}else if(!decisions.length)toast('The decision register is already empty.');break;
case 'clear-chat':messages=[];render();toast('Conversation cleared.');break;
}});
document.addEventListener('submit',event=>{if(event.target.id==='chat-form'){event.preventDefault();const q=document.querySelector('#question').value.trim();if(q)ask(q);}});
document.addEventListener('change',async event=>{const t=event.target;switch(t.id){case 'graph-type':graphType=t.value;render();break;case 'graph-depth':graphDepth=Number(t.value);render();break;case 'impact-select':impactTarget=t.value;render();break;case 'portfolio-filter':portfolioFilter=t.value;render();break;case 'budget':budget=Number(t.value);render();break;case 'horizon':horizon=Number(t.value);render();break;case 'context-file':{const file=t.files[0];if(!file)break;if(file.size>2_000_000){toast('Import must be smaller than 2 MB.');break;}try{const imported=validateGraph(JSON.parse(await file.text()));graph=imported;saveLocal('cio-context',graph);selected=graph.nodes[0]?.id;impactTarget=graph.nodes.find(n=>['Technology','Application'].includes(n.type))?.id||selected;selectedInitiatives=[];preset='custom';messages=[];backend='Imported browser context';render();toast('Context validated and loaded. Previous data was replaced in this browser.');}catch(error){toast('Import rejected: '+error.message);}break;}}if(t.dataset.initiative){const id=t.dataset.initiative;selectedInitiatives=t.checked?[...new Set([...selectedInitiatives,id])]:selectedInitiatives.filter(x=>x!==id);preset='custom';render();}});
document.addEventListener('input',event=>{const t=event.target;if(t.id==='graph-search'||t.id==='portfolio-search'){const cursor=t.selectionStart;if(t.id==='graph-search')graphSearch=t.value.toLowerCase();else portfolioSearch=t.value.toLowerCase();render();const replacement=document.getElementById(t.id);replacement.focus();replacement.setSelectionRange(cursor,cursor);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){drawer=null;render();}if((event.key==='Enter'||event.key===' ')&&event.target.matches('.graph-node')){event.preventDefault();openGraph(event.target.dataset.graphnode);}if(event.key==='Tab'&&drawer){const focusables=[...document.querySelectorAll('.detail-drawer button,.detail-drawer a,.detail-drawer [tabindex="0"]')];const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
document.addEventListener('click',event=>{const t=event.target.closest('[data-domain],[data-journey-step],[data-review-kind],[data-editor-kind]');if(!t||!canLeaveEditor())return;if(t.dataset.domain)chooseDomain(t.dataset.domain);else if(t.dataset.journeyStep)moveJourney(Number(t.dataset.journeyStep));else if(t.dataset.reviewKind)reviewRecord(t.dataset.reviewKind,t.dataset.reviewId);else setEditor(t.dataset.editorKind);render();window.scrollTo({top:0});});
 document.addEventListener('input',event=>{if(event.target.closest('#context-editor'))contextDirty=true;});
 document.addEventListener('change',event=>{if(event.target.closest('#context-editor'))contextDirty=true;});
document.addEventListener('change',event=>{if(event.target.id==='editor-record'){if(!canLeaveEditor()){event.target.value=getEditor().id;return;}setEditor(getEditor().kind,event.target.value);render();}});
document.addEventListener('submit',event=>{
 // A control named "id" shadows HTMLFormElement.id; use the DOM attribute.
 if(event.target.getAttribute('id')!=='context-editor')return;
 event.preventDefault();
 try{
  const {kind,id}=getEditor(),form=new FormData(event.target),record=Object.fromEntries(form);
  for(const key of Object.keys(record))if(typeof record[key]==='string')record[key]=record[key].trim();
  record.validated=form.has('validated');
  for(const key of ['investment','annualSaving','durationMonths','annualCost','businessValue','health','risk']){if(record[key]==='')record[key]=undefined;else if(record[key]!==undefined)record[key]=Number(record[key]);}
  if(!id&&graph[kind==='node'?'nodes':'edges'].some(x=>x.id===record.id))throw new Error('This ID already exists. Select the record to edit it.');
  const next=saveContextRecord(graph,kind,record);
  if(!saveLocal('cio-context',next))return;
  graph=next;backend='Edited browser context';messages=[];setEditor(kind,record.id);render();toast('Context saved in this browser. Shared module evidence has been refreshed.');
 }catch(error){document.querySelector('#editor-error').textContent=error.message;}
});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'overview';if(next!==page){page=next;drawer=null;render();}});
async function initialize(){if(localGraph){try{graph=validateGraph(localGraph);backend='Imported browser context';selected=graph.nodes[0]?.id;}catch{toast('Saved context was invalid. Restoring demo data.');}}else{try{const response=await fetch('./api/context');if(response.ok&&response.headers.get('content-type')?.includes('application/json')){const payload=await response.json();graph=validateGraph(payload.graph);backend=payload.mode==='neo4j'?'Neo4j connected':'Local demo API';}}catch{/* Static hosting intentionally runs without an API. */}}render();}
render();initialize();
